SELECT *
FROM gl_promotion_claim
WHERE tenant_id = #{tenantId}
  AND promotion_id = #{promotionId}
  AND member_id = #{memberId}
  AND del_flag = '0'
LIMIT 1

SELECT *
FROM gl_promotion_claim
WHERE tenant_id = #{tenantId}
  AND promotion_id = #{promotionId}
  AND member_id = #{memberId}
  AND claim_date = #{claimDate}
  AND del_flag = '0'
LIMIT 1

SELECT *
FROM gl_promotion_claim
WHERE tenant_id = #{tenantId}
  AND member_id = #{memberId}
  AND del_flag = '0'
ORDER BY create_time DESC
